// WalletServiceServer is the server API for WalletService service.
// All implementations must embed UnimplementedWalletServiceServer
// for forward compatibility.
type WalletServiceServer interface {
	// GetWallet returns the caller's own wallet: ?owner_type=OWNER_TYPE_RIDER or OWNER_TYPE_DRIVER.
	GetWallet(context.Context, *GetWalletRequest) (*GetWalletResponse, error)
	TopUp(context.Context, *TopUpRequest) (*TopUpResponse, error)
	SettleTrip(context.Context, *SettleTripRequest) (*SettleTripResponse, error)
	// ListTransactions lists the caller's own wallet history: ?owner_type=&limit=.
	ListTransactions(context.Context, *ListTransactionsRequest) (*ListTransactionsResponse, error)
	// CheckDriverStanding tells a driver whether they can take trips and how much to deposit if not.
	CheckDriverStanding(context.Context, *CheckDriverStandingRequest) (*CheckDriverStandingResponse, error)
	// RequestPayout asks for the driver's own money: the amount is held (it
	// leaves the balance now) and a payout request waits for staff, who pay it
	// outside the platform and mark it paid, or reject it (the money comes
	// back). One open request at a time; idempotency_key makes a retry safe.
	RequestPayout(context.Context, *RequestPayoutRequest) (*RequestPayoutResponse, error)
	// ListPayouts is the driver's own payout requests, newest first.
	ListPayouts(context.Context, *ListPayoutsRequest) (*ListPayoutsResponse, error)
	// GetTripSettlement tells how a settled trip's fare was paid: what left the rider's
	// wallet and how much cash the driver collects. ?owner_type=&owner_id= is the caller's
	// own wallet, and only the rider and the driver of the trip can read it (anyone else,
	// like a trip that is not settled yet, gets NOT_FOUND). A driver also sees the
	// commission and their earning; a rider does not.
	GetTripSettlement(context.Context, *GetTripSettlementRequest) (*GetTripSettlementResponse, error)
	// RecordTripChange is how a driver reports that the rider handed over more cash than the
	// trip's cash part and there was no change to give back: the difference is credited to the
	// rider's wallet. The driver sends only cash_received (all the cash handed over); the change
	// is worked out here. The platform pays: nothing is taken from the driver. Only the trip's
	// own driver, after the trip is settled, once per trip (the same amount again is harmless),
	// and at most the deployment's max_change_credit.
	RecordTripChange(context.Context, *RecordTripChangeRequest) (*RecordTripChangeResponse, error)
	// InitiateTopUp starts a top-up of the caller's own wallet (a rider's or
	// a driver's) through a payment provider (zaincash, the default): a
	// pending record and a payment session on the provider's own page, whose
	// URL the app opens. The customer pays there, so a card number or a
	// wallet PIN never reaches the platform. The wallet is credited when the
	// provider's notification says the payment succeeded; GetTopUp tells the
	// app how it ended. Within the deployment's top-up limits.
	InitiateTopUp(context.Context, *InitiateTopUpRequest) (*InitiateTopUpResponse, error)
	GetTopUp(context.Context, *GetTopUpRequest) (*GetTopUpResponse, error)
	// TipDriver gives the trip's driver a tip from the rider's wallet: once
	// per trip, within 72 hours of a completed (settled) trip, within the
	// deployment's tip limits; the driver gets all of it (no commission). The
	// same idempotency_key again is the same tip.
	TipDriver(context.Context, *TipDriverRequest) (*TipDriverResponse, error)
	// SendTransfer sends money from the rider's wallet to another registered
	// rider's, by the phone the other signs in with (E.164, e.g.
	// +9647701234567), confirmed with the sender's wallet PIN. The same
	// idempotency_key again is the same transfer (never a second one); with
	// another recipient or amount it is refused. Limits: the least and most
	// one transfer may move, and how much and how many in any 24 hours
	// (wallet config). The recipient is told (push).
	SendTransfer(context.Context, *SendTransferRequest) (*SendTransferResponse, error)
	// ListTransfers is the rider's transfers, sent and received, newest first.
	ListTransfers(context.Context, *ListTransfersRequest) (*ListTransfersResponse, error)
	// Money requests: a rider asks for money, from one registered rider (by
	// phone: they are told) or from whoever opens its code (a link or a QR
	// code built from the code). Paying one is a transfer from the payer with
	// their PIN, within the transfer limits. It stays pending until paid,
	// declined (by the rider it is for), cancelled (by the requester) or it
	// expires (72 hours by default, 1-168).
	CreateMoneyRequest(context.Context, *CreateMoneyRequestRequest) (*MoneyRequestResponse, error)
	// ListMoneyRequests: role outgoing (asked by this rider) or incoming (for
	// this rider, or paid by them); status pending, paid, declined, cancelled
	// or expired. Newest first.
	ListMoneyRequests(context.Context, *ListMoneyRequestsRequest) (*ListMoneyRequestsResponse, error)
	// GetMoneyRequest opens a request by its code (after scanning its QR code
	// or following its link). A request for one rider is seen only by that
	// rider and the requester.
	GetMoneyRequest(context.Context, *GetMoneyRequestRequest) (*MoneyRequestResponse, error)
	PayMoneyRequest(context.Context, *PayMoneyRequestRequest) (*PayMoneyRequestResponse, error)
	DeclineMoneyRequest(context.Context, *CloseMoneyRequestRequest) (*MoneyRequestResponse, error)
	CancelMoneyRequest(context.Context, *CloseMoneyRequestRequest) (*MoneyRequestResponse, error)
	// GetStatement is the wallet's ledger for a period, with the balance
	// before and after it and what came in and went out. direction in / out
	// and types narrow the entries (and the totals); the opening and closing
	// balances are the wallet's, whatever the filter. Newest first.
	GetStatement(context.Context, *GetStatementRequest) (*GetStatementResponse, error)
	// GetRiderDues is what a rider still owes from cancelled trips' fees (the
	// money reaching their wallet pays it off first), and whether they may
	// request trips meanwhile (trip-service asks, with the internal token).
	GetRiderDues(context.Context, *GetRiderDuesRequest) (*GetRiderDuesResponse, error)
	// Vouchers: prepaid codes the platform issues in batches and sells through
	// a seller (ZainCash, shops); a rider types one in to credit their wallet.
	// Staff with vouchers.manage create a batch (its codes are generated here
	// and kept encrypted), export it ONCE (the only time the codes are shown;
	// after that only their hashes remain), and may cancel a batch or void one
	// voucher. A voucher is redeemable once its batch is exported, until it
	// expires, once.
	CreateVoucherBatch(context.Context, *CreateVoucherBatchRequest) (*VoucherBatchResponse, error)
	// ListVoucherBatches: newest first; status created, exported or cancelled.
	ListVoucherBatches(context.Context, *ListVoucherBatchesRequest) (*ListVoucherBatchesResponse, error)
	GetVoucherBatch(context.Context, *GetVoucherBatchRequest) (*VoucherBatchResponse, error)
	// ExportVoucherBatch returns every code of a created batch, once, and makes
	// the batch redeemable. The codes are not kept: a lost export is a batch to
	// cancel and issue again.
	ExportVoucherBatch(context.Context, *ExportVoucherBatchRequest) (*ExportVoucherBatchResponse, error)
	// CancelVoucherBatch stops every voucher of the batch not redeemed yet.
	CancelVoucherBatch(context.Context, *CancelVoucherBatchRequest) (*VoucherBatchResponse, error)
	// GetVoucher looks one voucher up by the serial printed next to its code.
	GetVoucher(context.Context, *GetVoucherRequest) (*VoucherResponse, error)
	// VoidVoucher stops one voucher not redeemed yet (a card reported lost).
	VoidVoucher(context.Context, *VoidVoucherRequest) (*VoucherResponse, error)
	// RedeemVoucher credits the rider's wallet with a voucher's amount (what
	// they owe from cancelled trips' fees is paid from it first). The same
	// rider redeeming the same code again gets the same redemption back.
	// Wrong codes are counted: after too many in a while the rider waits
	// (RESOURCE_EXHAUSTED).
	RedeemVoucher(context.Context, *RedeemVoucherRequest) (*RedeemVoucherResponse, error)
	// Staff money operations. wallets.read: look at any wallet and its
	// statement. wallets.adjust: correct a balance, refund a trip.
	// payouts.manage: work the payout queue. Every call is audited.
	InspectWallet(context.Context, *InspectWalletRequest) (*InspectWalletResponse, error)
	GetStatementForStaff(context.Context, *GetStatementRequest) (*GetStatementResponse, error)
	// AdjustWallet credits (positive) or debits (negative) a wallet with a
	// reason: an adjustment row. A rider's balance never goes below zero; a
	// driver's may (their commission balance), with the suspension rule.
	AdjustWallet(context.Context, *AdjustWalletRequest) (*AdjustmentResponse, error)
	// RefundTrip gives a rider back money for a settled trip (or a cancelled
	// trip's fee), paid by the platform, or partly taken back from the driver
	// (driver_amount). All the refunds of a trip add up to at most its fare (or
	// fee). Like any money reaching the wallet it pays unpaid fees first, so
	// refunding a fee still owed waives it.
	RefundTrip(context.Context, *RefundTripRequest) (*AdjustmentResponse, error)
	ListTripRefunds(context.Context, *ListTripRefundsRequest) (*ListTripRefundsResponse, error)
	// The payout queue: status pending, approved, paid or rejected; oldest
	// first, so the queue is worked in order.
	ListPayoutRequests(context.Context, *ListPayoutRequestsRequest) (*ListPayoutsResponse, error)
	ApprovePayout(context.Context, *ApprovePayoutRequest) (*PayoutResponse, error)
	// MarkPayoutPaid records that the money reached the driver (a pending or
	// approved request), with the transfer's reference.
	MarkPayoutPaid(context.Context, *MarkPayoutPaidRequest) (*PayoutResponse, error)
	// RejectPayout gives the held amount back to the driver's wallet.
	RejectPayout(context.Context, *RejectPayoutRequest) (*PayoutResponse, error)
	// ProcessZainCashWebhook receives ZainCash's server-to-server payment
	// notification. Called directly by ZainCash, not by an authenticated
	// platform client — exempted from the auth interceptor same as the
	// health check (see authentication_interceptor.go).
	ProcessZainCashWebhook(context.Context, *ProcessZainCashWebhookRequest) (*ProcessZainCashWebhookResponse, error)
	mustEmbedUnimplementedWalletServiceServer()
}

